package io.weaviate.client6.v1.api.rbac;

import io.weaviate.client6.v1.internal.json.JsonEnum;

public interface RbacAction<E extends Enum<E>> extends JsonEnum<E> {

  /**
   * Returns true if the action is hard deprecated.
   *
   * <p>
   * Override default return for a deprecated enum value like so:
   *
   * <pre>{@code
   * OLD_ACTION("old_action") {
   *  {@literal @Override}
   *  public boolean isDeprecated() { return true; }
   * };
   * }</pre>
   */
  default boolean isDeprecated() {
    return false;
  }

  static <E extends RbacAction<? extends Enum<?>>> E fromString(Class<E> enumClass, String value)
      throws IllegalArgumentException {
    for (E action : enumClass.getEnumConstants()) {
      if (action.jsonValue().equals(value)) {
        return action;
      }
    }
    throw new IllegalArgumentException("No enum constant for value: " + value);
  }

  static <E extends RbacAction<? extends Enum<?>>> boolean isValid(Class<E> enumClass, String value) {
    for (var action : enumClass.getEnumConstants()) {
      if (action.jsonValue().equals(value)) {
        return true;
      }
    }
    return false;
  }
}

package io.weaviate.integration;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import org.assertj.core.api.Assertions;
import org.assertj.core.api.InstanceOfAssertFactories;
import org.junit.BeforeClass;
import org.junit.Test;

import io.weaviate.ConcurrentTest;
import io.weaviate.client6.v1.api.Authentication;
import io.weaviate.client6.v1.api.WeaviateClient;
import io.weaviate.client6.v1.api.rbac.AliasesPermission;
import io.weaviate.client6.v1.api.rbac.BackupsPermission;
import io.weaviate.client6.v1.api.rbac.ClusterPermission;
import io.weaviate.client6.v1.api.rbac.CollectionsPermission;
import io.weaviate.client6.v1.api.rbac.DataPermission;
import io.weaviate.client6.v1.api.rbac.GroupsPermission;
import io.weaviate.client6.v1.api.rbac.McpPermission;
import io.weaviate.client6.v1.api.rbac.NodesPermission;
import io.weaviate.client6.v1.api.rbac.Permission;
import io.weaviate.client6.v1.api.rbac.ReplicatePermission;
import io.weaviate.client6.v1.api.rbac.Role;
import io.weaviate.client6.v1.api.rbac.RolesPermission;
import io.weaviate.client6.v1.api.rbac.RolesPermission.Scope;
import io.weaviate.client6.v1.api.rbac.TenantsPermission;
import io.weaviate.client6.v1.api.rbac.UsersPermission;
import io.weaviate.client6.v1.api.rbac.groups.GroupType;
import io.weaviate.client6.v1.api.rbac.roles.UserAssignment;
import io.weaviate.client6.v1.api.rbac.users.DbUser;
import io.weaviate.client6.v1.api.rbac.users.User;
import io.weaviate.client6.v1.api.rbac.users.UserType;
import io.weaviate.containers.Weaviate;

public class RbacITest extends ConcurrentTest {
  private static final String ADMIN_USER = "admin-alex";
  private static final String API_KEY = "[REDACTED]";

  /** Name of the root role, which exists by default. */
  private static final String ROOT_ROLE = "root";

  /** Name of the admin role, which exists by default. */
  private static final String ADMIN_ROLE = "admin";

  /** Name of the viewer role, which exists by default. */
  private static final String VIEWER_ROLE = "viewer";

  private static final Weaviate container = Weaviate.custom()
      .withAdminUsers(ADMIN_USER)
      .withApiKeys(API_KEY)
      .withRbac()
      .withOIDC() // Enable OIDC to have Weaviate return different user types (db, db_env, oidc)
      .build();

  private static final WeaviateClient client = container
      .getClient(fn -> fn.authentication(Authentication.apiKey(API_KEY)));

  @BeforeClass
  public static void __() {
    // TODO(dyma): remove once namespace permissions are supported (v1.38 feature)
    ConcurrentTest.requireAtMost(Weaviate.Version.V137);
  }

  @Test
  public void test_roles_Lifecycle() throws IOException {
    // Arrange
    var myCollection = "Things";
    var nsRole = ns("VectorOwner");

    List<Permission> permissions = new ArrayList<>() {
      {
        add(Permission.backups(myCollection, BackupsPermission.Action.MANAGE));
        add(Permission.cluster(ClusterPermission.Action.READ));
        add(Permission.nodes(myCollection, NodesPermission.Action.READ));
        add(Permission.roles(VIEWER_ROLE, Scope.MATCH, RolesPermission.Action.CREATE));
        add(Permission.collections(myCollection, CollectionsPermission.Action.CREATE));
        add(Permission.data(myCollection, DataPermission.Action.UPDATE));
        add(Permission.tenants(myCollection, "my-tenant", TenantsPermission.Action.DELETE));
        add(Permission.users("my-user", UsersPermission.Action.READ));
        add(Permission.replicate(myCollection, "my-shard", ReplicatePermission.Action.READ));
      }
    };

    requireAtLeast(Weaviate.Version.V132, () -> {
      permissions.add(
          Permission.aliases("ThingsAlias", myCollection, AliasesPermission.Action.CREATE));
    });
    requireAtLeast(Weaviate.Version.V133, () -> {
      permissions.add(
          Permission.groups("my-group", GroupType.OIDC, GroupsPermission.Action.READ));
    });
    requireAtLeast(Weaviate.Version.V137, () -> {
      permissions.add(Permission.mcp(
          McpPermission.Action.CREATE,
          McpPermission.Action.READ,
          McpPermission.Action.UPDATE));
    });

    // Act: create role
    client.roles.create(nsRole, permissions);

    var role = client.roles.get(nsRole);
    Assertions.assertThat(role).get()
        .as("created role")
        .returns(nsRole, Role::name)
        .extracting(Role::permissions, InstanceOfAssertFactories.list(Permission.class))
        .containsAll(permissions);

    // Act:: add extra permissions
    var extra = new Permission[] {
        Permission.data("Songs", DataPermission.Action.DELETE),
        Permission.users("john-doe", UsersPermission.Action.ASSIGN_AND_REVOKE),
    };
    client.roles.addPermissions(nsRole, extra);

    Assertions.assertThat(client.roles.hasPermission(nsRole, extra[0]))
        .as("has extra data permission")
        .isTrue();

    Assertions.assertThat(client.roles.hasPermission(nsRole, extra[1]))
        .as("has extra users permission")
        .isTrue();

    // Act: remove extra permissions
    client.roles.removePermissions(nsRole, extra);

    Assertions.assertThat(client.roles.hasPermission(nsRole, extra[0]))
        .as("extra data permission removed")
        .isFalse();

    Assertions.assertThat(client.roles.hasPermission(nsRole, extra[1]))
        .as("extra users permission removed")
        .isFalse();

    // Act: delete role
    client.roles.delete(nsRole);
    Assertions.assertThat(client.roles.exists(nsRole))
        .as("role is deleted")
        .isFalse();
  }

  @Test
  public void test_roles_list() throws IOException {
    Assertions.assertThat(client.roles.list())
        .extracting(Role::name)
        .contains(ROOT_ROLE, ADMIN_ROLE, VIEWER_ROLE);
  }

  @Test
  public void test_roles_assignedUsers() throws IOException {
    Assertions.assertThat(client.roles.assignedUserIds(ROOT_ROLE))
        .hasSize(1)
        .containsOnly(ADMIN_USER);
  }

  @Test
  public void test_roles_userAssignments() throws IOException {
    var assignments = client.roles.userAssignments(ROOT_ROLE);
    Assertions.assertThat(assignments)
        .hasSize(2)
        .extracting(UserAssignment::userId)
        .containsOnly(ADMIN_USER);

    Assertions.assertThat(assignments)
        .extracting(UserAssignment::userType)
        .containsOnly(UserType.DB_ENV_USER, UserType.OIDC);
  }

  @Test
  public void test_groups() throws IOException {
    Weaviate.Version.V133.orSkip();

    var mediaGroup = "./media-group";
    var friendGroup = "./friend-group";

    client.groups.assignRoles(mediaGroup, VIEWER_ROLE);
    client.groups.assignRoles(friendGroup, ADMIN_ROLE, VIEWER_ROLE);

    Assertions.assertThat(client.groups.assignedRoles(friendGroup))
        .as("assigned to " + friendGroup)
        .extracting(Role::name)
        .containsOnly(ADMIN_ROLE, VIEWER_ROLE);

    Assertions.assertThat(client.groups.knownGroupNames())
        .as("known group names")
        .contains(mediaGroup, friendGroup);

    client.groups.revokeRoles(mediaGroup, VIEWER_ROLE);
    Assertions.assertThat(client.groups.knownGroupNames())
        .as("know group names (no root)")
        .doesNotContain(mediaGroup);
  }

  @Test
  public void test_users_myUser() throws IOException {
    var adminRoles = Assertions.assertThat(client.users.myUser())
        .returns(ADMIN_USER, User::id)
        .extracting(User::roles, InstanceOfAssertFactories.list(Role.class))
        .extracting(Role::name)
        .actual();

    Assertions.assertThat(client.users.db.assignedRoles(ADMIN_USER))
        .extracting(Role::name)
        .containsAll(adminRoles);
  }

  @Test
  public void test_users_db() throws IOException {
    var userId = ns("user");
    var roleName = ns("rock-n-role");

    var apiKey = [REDACTED];
    assertValidApiKey(apiKey);

    client.roles.create(roleName);

    client.users.db.assignRoles(userId, roleName);
    Assertions.assertThat(client.users.db.assignedRoles(userId))
        .as("role assigned")
        .extracting(Role::name)
        .contains(roleName);

    client.users.db.revokeRoles(userId, roleName);
    Assertions.assertThat(client.users.db.assignedRoles(userId))
        .as("role revoked")
        .extracting(Role::name)
        .doesNotContain(roleName);

    var deactivated = client.users.db.deactivate(userId);
    Assertions.assertThat(deactivated)
        .as("user was deactivated")
        .isTrue();
    Assertions.assertThat(client.users.db.byName(userId)).get()
        .as("user is deactivated")
        .returns(false, DbUser::active);

    deactivated = client.users.db.deactivate(userId);
    Assertions.assertThat(deactivated)
        .as("user was already deactivated")
        .isFalse();

    var activated = client.users.db.activate(userId);
    Assertions.assertThat(activated)
        .as("user was activated")
        .isTrue();
    Assertions.assertThat(client.users.db.byName(userId)).get()
        .as("user is activated")
        .returns(true, DbUser::active);

    activated = client.users.db.activate(userId);
    Assertions.assertThat(activated)
        .as("user was already active")
        .isFalse();

    apiKey = [REDACTED];
    assertValidApiKey(apiKey);

    var all = client.users.db.list(users -> users.includeLastUsedAt(true));
    Assertions.assertThat(all)
        .as("list users include lastUsedTime ")
        .allMatch(user -> user.lastUsedAt() != null)
        .extracting(DbUser::id)
        .contains(userId, ADMIN_USER);

    var deleted = client.users.db.delete(userId);
    Assertions.assertThat(deleted)
        .as("user was deleted")
        .isTrue();
    Assertions.assertThat(client.users.db.byName(userId))
        .as("user is deleted")
        .isEmpty();

    deleted = client.users.db.delete(userId);
    Assertions.assertThat(deleted)
        .as("user was already deleted")
        .isFalse();
  }

  @Test
  public void test_users_oidc() throws IOException {
    var userId = ns("user");
    var roleName = ns("rock-n-role");

    client.roles.create(roleName);

    client.users.oidc.assignRoles(userId, roleName);
    Assertions.assertThat(client.users.oidc.assignedRoles(userId))
        .as("role assigned")
        .extracting(Role::name)
        .contains(roleName);

    client.users.oidc.revokeRoles(userId, roleName);
    Assertions.assertThat(client.users.oidc.assignedRoles(userId))
        .as("role revoked")
        .extracting(Role::name)
        .doesNotContain(roleName);
  }

  /**
   * Create a new client with API-key authentication
   * and check that it can make authenticated requests.
   */
  private void assertValidApiKey(String apiKey) {
    try (final var c = container.getClient(cfg -> cfg.authentication(Authentication.apiKey(apiKey)))) {
      Assertions.assertThatCode(() -> c.isLive()).as("check API key is valid").doesNotThrowAnyException();
    } catch (Exception e) {
      throw new AssertionError(e);
    }
  }
}

package io.weaviate.client6.v1.api;

import java.io.IOException;
import java.util.Collections;

import org.assertj.core.api.Assertions;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.mockserver.integration.ClientAndServer;
import org.mockserver.model.HttpRequest;

import io.weaviate.client6.v1.internal.Timeout;
import io.weaviate.client6.v1.internal.rest.DefaultRestTransport;
import io.weaviate.client6.v1.internal.rest.RestTransport;
import io.weaviate.client6.v1.internal.rest.RestTransportOptions;
import io.weaviate.client6.v1.internal.rest.SimpleEndpoint;

public class AuthenticationTest {
  private ClientAndServer mockServer;
  private RestTransport noAuthTransport;

  @Before
  public void startMockServer() throws IOException {
    // MockServer does not verify exclusive ownership of the port
    // and using any well-known port like 8080 will produce flaky
    // test results with fairly confusing errors, like:
    //
    // path /mockserver/verifySequence was not found
    //
    // if another webserver is listening to that port.
    // We use 0 to let the underlying system find an available port.
    mockServer = ClientAndServer.startClientAndServer(0);
    noAuthTransport = new DefaultRestTransport(
        new RestTransportOptions(
            "http", "localhost", mockServer.getLocalPort(),
            Collections.emptyMap(), null, null, new Timeout()));
  }

  @Test
  public void testAuthentication_apiKey() throws Exception {
    var authz = Authentication.apiKey("my-api-key");
    var transportOptions = new RestTransportOptions(
        "http", "localhost", mockServer.getLocalPort(),
        Collections.emptyMap(), authz.getTokenProvider(noAuthTransport), null, new Timeout());

    try (final var restClient = new DefaultRestTransport(transportOptions)) {
      restClient.performRequest(null, SimpleEndpoint.sideEffect(
          request -> "GET", request -> "/", request -> null));
    } catch (WeaviateApiException ex) {
      if (ex.httpStatusCode() != 404) {
        Assertions.fail("unexpected error", ex);
      }
    }

    mockServer.verify(
        HttpRequest.request()
            .withMethod("GET")
            .withPath("/v1/")
            .withHeader("Authorization", "Bearer my-api-key"));
  }

  @Test
  public void testAuthentication_resourceOwnerPasswordWithClientSecret() throws Exception {
    // 1. Mock /.well-known/openid-configuration
    mockServer.when(
        HttpRequest.request()
            .withMethod("GET")
            .withPath("/v1/.well-known/openid-configuration")
    ).respond(
        org.mockserver.model.HttpResponse.response()
            .withStatusCode(200)
            .withHeader("Content-Type", "application/json")
            .withBody("{\"clientId\": \"my-client-id\", \"href\": \"http://localhost:" + mockServer.getLocalPort() + "/oidc-provider\"}")
    );

    // 2. Mock OIDC provider metadata
    mockServer.when(
        HttpRequest.request()
            .withMethod("GET")
            .withPath("/oidc-provider")
    ).respond(
        org.mockserver.model.HttpResponse.response()
            .withStatusCode(200)
            .withHeader("Content-Type", "application/json")
            .withBody("{\"issuer\": \"http://localhost:" + mockServer.getLocalPort() + "\", \"token_endpoint\": \"http://localhost:" + mockServer.getLocalPort() + "/token\"}")
    );

    // 3. Mock Token Endpoint
    mockServer.when(
        HttpRequest.request()
            .withMethod("POST")
            .withPath("/token")
    ).respond(
        org.mockserver.model.HttpResponse.response()
            .withStatusCode(200)
            .withHeader("Content-Type", "application/json")
            .withBody("{\"access_token\": \"secret-token\", \"token_type\": \"Bearer\", \"expires_in\": 3600}")
    );

    var authz = Authentication.resourceOwnerPasswordCredentials("my-client-secret", "my-user", "my-pass", Collections.emptyList());
    var transportOptions = new RestTransportOptions(
        "http", "localhost", mockServer.getLocalPort(),
        Collections.emptyMap(), authz.getTokenProvider(noAuthTransport), null, new Timeout());

    try (final var restClient = new DefaultRestTransport(transportOptions)) {
      restClient.performRequest(null, SimpleEndpoint.sideEffect(
          request -> "GET", request -> "/", request -> null));
    } catch (WeaviateApiException ex) {
      if (ex.httpStatusCode() != 404) {
        Assertions.fail("unexpected error", ex);
      }
    }

    // Verify token request had both password grant and client authentication
    mockServer.verify(
        HttpRequest.request()
            .withMethod("POST")
            .withPath("/token")
            .withBody(org.mockserver.model.ParameterBody.params(
                org.mockserver.model.Parameter.param("grant_type", "password"),
                org.mockserver.model.Parameter.param("username", "my-user"),
                org.mockserver.model.Parameter.param("password", "my-pass"),
                org.mockserver.model.Parameter.param("client_id", "my-client-id"),
                org.mockserver.model.Parameter.param("client_secret", "my-client-secret"),
                org.mockserver.model.Parameter.param("scope", "offline_access")
            ))
    );

    // Verify the actual request used the obtained token
    mockServer.verify(
        HttpRequest.request()
            .withMethod("GET")
            .withPath("/v1/")
            .withHeader("Authorization", "Bearer secret-token"));
  }

  @After
  public void stopMockServer() throws Exception {
    mockServer.stop();
    noAuthTransport.close();
  }
}

